		return err
	}
	messages, err := parseKiloExport(raw)
	if err != nil {
		return err
	}
	encoded, err := encodeMessagesJSONL(messages)
	if err != nil {
		return err
	}
	return atomicWriteFile(sessionRef, encoded, 0o600)
}

